command:
// Registers a one-shot hook that intercepts the first lethal hit on the Tulpa
// and sets HP to 1 instead of 0. Removes itself after triggering.

const tulpaToken = canvas.tokens.placeables.find(t => t.actor?.name === "Tulpa");
if (!tulpaToken) {
  ui.notifications.warn("No Tulpa on canvas — Relentless not armed.");
  return;
}
const tulpa = tulpaToken.actor;

// Don't re-register if already used this casting
if (tulpa.getFlag("manifest-tulpa", "relentlessUsed")) {
  ui.notifications.warn("Relentless has already triggered this casting.");
  return;
}

let hookId;
hookId = Hooks.on("preUpdateActor", (actor, changes, _options, _userId) => {
  if (actor.uuid !== tulpa.uuid) return;

  const newHp = foundry.utils.getProperty(changes, "system.attributes.hp.value");
  if (newHp === undefined || newHp > 0) return; // Not a lethal hit

  // Intercept — floor at 1 instead of 0
  foundry.utils.setProperty(changes, "system.attributes.hp.value", 1);
  Hooks.off("preUpdateActor", hookId);
  actor.setFlag("manifest-tulpa", "relentlessUsed", true);

  ChatMessage.create({
    content: `<div style="text-align:center; padding:4px">
      <strong>⚡ Relentless!</strong><br>
      The Tulpa's will holds — it drops to 1 HP rather than falling.
    </div>`,
    speaker: ChatMessage.getSpeaker({ actor: tulpa })
  });
});

ui.notifications.info("Relentless armed — watching for lethal damage on the Tulpa.");
